def shortestTotalDistance(grid):
    rows, cols = len(grid), len(grid[0])
    W = cols + 2
    cell = [2] * ((rows + 2) * W)  # a border of obstacles avoids bounds checks
    for r in range(rows):
        for c in range(cols):
            cell[(r + 1) * W + c + 1] = grid[r][c]
    total = [0] * len(cell)
    reach = [0] * len(cell)
    buildings = [i for i, v in enumerate(cell) if v == 1]
    steps = (1, -1, W, -W)
    for b in buildings:
        seen = bytearray(len(cell))
        level = [b]
        d = 0
        while level:
            d += 1
            nxt = []
            for u in level:
                for s in steps:
                    v = u + s
                    if cell[v] == 0 and not seen[v]:
                        seen[v] = 1
                        total[v] += d
                        reach[v] += 1
                        nxt.append(v)
            level = nxt
    best = -1
    for i, v in enumerate(cell):
        if v == 0 and reach[i] == len(buildings) and (best == -1 or total[i] < best):
            best = total[i]
    return best
